package ma.enset.smartdevcollab.service;
import ma.enset.smartdevcollab.dto.TaskDtos.*; import ma.enset.smartdevcollab.entity.*; import ma.enset.smartdevcollab.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class TaskService{ private final TaskRepository tasks; private final ProjectRepository projects; private final UserRepository users; private final ActivityService activity;
 public TaskService(TaskRepository tasks,ProjectRepository projects,UserRepository users,ActivityService activity){this.tasks=tasks;this.projects=projects;this.users=users;this.activity=activity;}
 public List<Task> all(){return tasks.findAll();} public List<Task> byProject(Long id){return tasks.findByProjectId(id);} public Task create(TaskRequest r){ Project p=projects.findById(r.projectId()).orElseThrow(); User u=r.assignedToId()==null?null:users.findById(r.assignedToId()).orElse(null); Task t=Task.builder().title(r.title()).description(r.description()).project(p).assignedTo(u).status(r.status()==null?TaskStatus.TODO:r.status()).priority(r.priority()==null?Priority.MEDIUM:r.priority()).dueDate(r.dueDate()).deliverable(r.deliverable()).build(); t=tasks.save(t); activity.log(p,u,"a cree la tache: "+t.getTitle()); return t; }
 public Task update(Long id,TaskRequest r){ Task t=tasks.findById(id).orElseThrow(); if(r.title()!=null)t.setTitle(r.title()); if(r.description()!=null)t.setDescription(r.description()); if(r.status()!=null)t.setStatus(r.status()); if(r.priority()!=null)t.setPriority(r.priority()); if(r.assignedToId()!=null)t.setAssignedTo(users.findById(r.assignedToId()).orElse(null)); t.setDueDate(r.dueDate()); t.setDeliverable(r.deliverable()); Task saved=tasks.save(t); activity.log(saved.getProject(),saved.getAssignedTo(),"a modifie la tache: "+saved.getTitle()); return saved; }
 public Task status(Long id,StatusRequest r){ Task t=tasks.findById(id).orElseThrow(); t.setStatus(r.status()); Task saved=tasks.save(t); activity.log(saved.getProject(),saved.getAssignedTo(),"a deplace la tache '"+saved.getTitle()+"' vers "+r.status()); return saved; } public void delete(Long id){ tasks.deleteById(id); } }
